(function() {
    var type_impls = Object.fromEntries([["umshctl",[["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Radio-for-UlcpDevice%3CL%3E\" class=\"impl\"><a href=\"#impl-Radio-for-UlcpDevice%3CL%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;L&gt; Radio for UlcpDevice&lt;L&gt;<div class=\"where\">where\n    L: FrameLink,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmit\" class=\"method trait-impl\"><a href=\"#method.transmit\" class=\"anchor\">§</a><h4 class=\"code-header\">async fn <a class=\"fn\">transmit</a>(\n    &amp;mut self,\n    data: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: TxOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, TxError&lt;&lt;UlcpDevice&lt;L&gt; as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Transmit one frame and await the device’s confirmation.</p>\n<p>A confirmed transmit blocks the caller for up to\n<code>max(response_timeout, 3 seconds, 2 × t_frame_ms)</code> after refreshing the\ndevice’s frame duration, while the frame goes out on air. This\nis inherent to the half-duplex [<code>Radio::transmit</code>] contract and a real\nradio behaves the same way. Frames the device receives during this window\nare not lost—they are queued (see <a href=\"Self::wait_response\"><code>wait_response</code></a>\n→ <a href=\"Self::ingest\"><code>ingest</code></a>) and surface on the next\n<a href=\"Radio::poll_receive\"><code>poll_receive</code></a>. MAC-layer timers (ACK timeouts,\nretransmit deadlines) cannot advance while this future is pending, but\nthey are only <em>delayed</em>, not missed: the coordinator re-evaluates every\ndeadline against the current clock as soon as <code>transmit</code> returns, so a\ndeadline that came due mid-transmit fires immediately afterward.</p>\n</div></details><section id=\"associatedtype.Error\" class=\"associatedtype trait-impl\"><a href=\"#associatedtype.Error\" class=\"anchor\">§</a><h4 class=\"code-header\">type <a class=\"associatedtype\">Error</a> = UlcpError</h4></section><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_receive\" class=\"method trait-impl\"><a href=\"#method.poll_receive\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a class=\"fn\">poll_receive</a>(\n    &amp;mut self,\n    cx: &amp;mut <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/core/task/wake/struct.Context.html\" title=\"struct core::task::wake::Context\">Context</a>&lt;'_&gt;,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/task/poll/enum.Poll.html\" title=\"enum core::task::poll::Poll\">Poll</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;RxInfo, &lt;UlcpDevice&lt;L&gt; as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class='docblock'>Poll reception of one frame into <code>buf</code>. <a>Read more</a></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.max_frame_size\" class=\"method trait-impl\"><a href=\"#method.max_frame_size\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a class=\"fn\">max_frame_size</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a></h4></section></summary><div class='docblock'>Return the largest supported raw frame size.</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.t_frame_ms\" class=\"method trait-impl\"><a href=\"#method.t_frame_ms\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a class=\"fn\">t_frame_ms</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a></h4></section></summary><div class='docblock'>Return the approximate airtime for a maximum-length frame.</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.spreading_factor\" class=\"method trait-impl\"><a href=\"#method.spreading_factor\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a class=\"fn\">spreading_factor</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;</h4></section></summary><div class='docblock'>The LoRa spreading factor this radio is currently receiving with,\nwhen it knows. <a>Read more</a></div></details></div></details>","Radio","umshctl::mesh::CtlRadio"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-UlcpDevice%3CL%3E\" class=\"impl\"><a href=\"#impl-UlcpDevice%3CL%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;L&gt; UlcpDevice&lt;L&gt;<div class=\"where\">where\n    L: FrameLink,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.attach_mode\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.attach_mode\" class=\"fn\">attach_mode</a>(&amp;self) -&gt; AttachMode</h4></section></summary><div class=\"docblock\"><p>Which relationship this handle has with the device.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.is_remote\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.is_remote\" class=\"fn\">is_remote</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Whether this handle reaches the device over the mesh rather than a\nwire, and is therefore bounded by what the administrative binding\ncarries.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.new\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.new\" class=\"fn\">new</a>(\n    link: L,\n    config: UlcpDeviceConfig,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;UlcpDevice&lt;L&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Attach to a device: reset it, verify the protocol version, apply\nthe RF configuration, and enable the PHY.</p>\n<p>This is the minimal-protocol attach: <code>CMD_RST</code> discards a\nfull-protocol device’s session-independent state visibility (and\nwith a saved snapshot the post-reset values come from the\nsnapshot, not the documented defaults). A host cooperating with\nan autonomously operating device should use\n[<code>Self::attach_existing</code>] instead.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.attach_existing\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.attach_existing\" class=\"fn\">attach_existing</a>(\n    link: L,\n    config: UlcpDeviceConfig,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;UlcpDevice&lt;L&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Attach to an already-operating device as its <strong>tethered host</strong>:\nthe one host whose traffic it filters, queues and acknowledges.</p>\n<p>This is the full-protocol attach (spec §Attach, Detach, and\nSynchronization): attach implies no known state, so the host\nsynchronizes by fetching. Only the identity handshake runs here\n—retained <code>PROP_LAST_STATUS</code> (the reset cause, preserved for\n[<code>Self::boot_status</code>] and [<code>Self::sync</code>]), the protocol version\ncheck, <code>PROP_DEV_VERSION</code>, <code>PROP_PHY_MTU</code>, and the current frame\nairtime. The PHY keeps\nwhatever configuration and enable state it had; queued frames\nand provisioning are untouched. Follow with [<code>Self::sync</code>],\n[<code>Self::provision</code>], and drain the queue when ready.</p>\n<p>Use [<code>Self::attach_administrative</code>] to configure a device you do\nnot intend to tether to—one phone administering ten repeaters\nmust not write <code>PROP_HOST_KEY</code> on any of them.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.attach_administrative\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.attach_administrative\" class=\"fn\">attach_administrative</a>(\n    link: L,\n    config: UlcpDeviceConfig,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;UlcpDevice&lt;L&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Attach to an already-operating device to <strong>administer</strong> it:\nconfigure its own identity, radio, and behavior without becoming\nits host.</p>\n<p>Commissioning and tethering are different relationships and this\nis the difference made mechanical. The handle refuses every\nhost-domain write—<code>PROP_HOST_KEY</code>, the host key tables, the\nfilter table, the delegation policy, and [<code>Self::provision</code>]—\nwith [<code>UlcpError::AdministrativeAttach</code>]. Everything\nelse, including the device identity and the saved snapshot, works\nnormally.</p>\n<p>A device may be administered by many hosts over its lifetime and\ntethered to at most one at a time; nothing about administering it\ndisturbs whichever host it is currently serving.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.open_remote\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.open_remote\" class=\"fn\">open_remote</a>(link: L, config: UlcpDeviceConfig) -&gt; UlcpDevice&lt;L&gt;</h4></section></summary><div class=\"docblock\"><p>Open a handle on a device reached over the mesh, through the Node\nManagement binding.</p>\n<p>Nothing goes on the air. An attach down a wire opens with a few\nreads because the link has just come up and the host knows\nnothing about what is on the other end; none of that is a\nhandshake in the sense of establishing anything, because the\ndevice is told nothing and holds no state for it. Over the\nbinding those reads would be exchanges on the air, minutes of\nthem in bad conditions, spent before the command you actually\nasked for. A command that wants the firmware version or the boot\nstatus reads it, and pays for it then.</p>\n<p>So [<code>Self::dev_version</code>], [<code>Self::dev_model</code>], and\n[<code>Self::boot_status</code>] are empty on this handle, and the frame\nceiling comes from the binding—[<code>umsh_node_mgmt::REQUEST_MAX</code>],\nwhich bounds a request here more tightly than the device’s own\nPHY MTU does—rather than from asking. Give <code>config</code> the\ndevice’s PHY and a response timeout that outlasts the binding’s\nown retry budget, or a slow answer becomes a transport error here\nbefore the exchange engine has finished trying.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.reattach\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.reattach\" class=\"fn\">reattach</a>(&amp;mut self, link: L) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Give this handle a new transport to the same device.</p>\n<p>Everything the handle <em>is</em> survives—its attach mode, its\nconfiguration, its trace sink—and everything it <em>held about the\nold link</em> is discarded: queued frames and responses, latched\nnotices, the transaction-identifier space. What it <em>learned</em> at\nattach survives too: the device on the other end is the one it\nattached to, so its version, model, MTU and frame time are not\nasked for again. The one thing that can have changed in between\nis whether it rebooted, so the retained status is re-read; that\nsingle exchange is also what proves the new link is live.</p>\n<p>The old transport is dropped here, not closed. A transport the\ndevice admits one of at a time (BLE) must be closed <em>before</em>\nthe new one is opened, or the device is still occupied by the\nstale connection and never found; that is the caller’s job, since\nonly the caller knows what a link is.</p>\n<p>The state is swapped before the first await, so a handshake that\nis cancelled leaves a live link behind it; whatever the handshake\ndid not get to learn, the next exchange corrects.</p>\n<p>A mesh handle has no transport of its own to replace: the radio\nunderneath it is what gets reattached, and asking for this on the\nhandle is refused.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.link_lost\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.link_lost\" class=\"fn\">link_lost</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Whether the transport has reported itself gone since the handle\nwas attached or last reattached. Every call on the handle fails\nwhile this holds; [<code>Self::reattach</code>] is the way out.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.link_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.link_mut\" class=\"fn\">link_mut</a>(&amp;mut self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.reference.html\">&amp;mut L</a></h4></section></summary><div class=\"docblock\"><p>Borrow the transport, for whoever has to close or replace it.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.into_link\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.into_link\" class=\"fn\">into_link</a>(self) -&gt; L</h4></section></summary><div class=\"docblock\"><p>Give up this handle and recover the transport underneath it.</p>\n<p>The link stays open, so the device sees no detach and keeps its\nsession-scoped state: this releases the <em>host’s</em> bookkeeping, not\nthe connection. Re-attaching the returned link produces a fresh\nhandle, which is how a long-lived interactive host changes\n[<code>AttachMode</code>]—administrative for inspection, tethered for the\none command that establishes a host domain—without making the\nuser wait through a BLE reconnect.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_frame_trace\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.set_frame_trace\" class=\"fn\">set_frame_trace</a>(\n    &amp;mut self,\n    trace: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/boxed/struct.Box.html\" title=\"struct alloc::boxed::Box\">Box</a>&lt;dyn <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(TraceDirection, &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>) + <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/marker/trait.Send.html\" title=\"trait core::marker::Send\">Send</a>&gt;&gt;,\n)</h4></section></summary><div class=\"docblock\"><p>Install (or clear) a per-frame trace sink. Every frame sent and\nevery frame received is reported as a one-line summary (see\n[<code>describe_frame</code>]), so a failure can be placed at the host API,\nframing, session, storage, or radio boundary.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.dev_version\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.dev_version\" class=\"fn\">dev_version</a>(&amp;self) -&gt; &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a></h4></section></summary><div class=\"docblock\"><p>The device’s firmware version string (<code>PROP_DEV_VERSION</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.dev_model\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.dev_model\" class=\"fn\">dev_model</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>&gt;</h4></section></summary><div class=\"docblock\"><p>The device’s hardware model (<code>PROP_DEV_MODEL</code>), or <code>None</code> on a\ndevice that does not implement the optional property—a\nsimulator, or firmware predating it.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.device_name\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.device_name\" class=\"fn\">device_name</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Fetch the device’s human-readable <code>PROP_DEV_NAME</code>.</p>\n<p>Read as the device reports it. The length and content rules bind\nthe writer—[<code>Self::set_device_name</code>] keeps to them—and a name\nthat breaks them is still the device’s name, shown as best it can\nbe.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_device_name\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_device_name\" class=\"fn\">set_device_name</a>(&amp;mut self, name: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the device’s human-readable <code>PROP_DEV_NAME</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.battery_status\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.battery_status\" class=\"fn\">battery_status</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;BatteryStatus&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Fetch a live battery status snapshot (<code>PROP_BATTERY</code>).</p>\n<p><code>Ok(None)</code> means the device is not battery powered.\n<code>Ok(Some(status))</code> with every field <code>None</code> means battery powered\nwith unsupported reporting. A measurement the device cannot\ncurrently obtain surfaces as a command failure, never as <code>None</code>—\nbattery is live telemetry, so this is deliberately not part of\n[<code>UlcpDevice::sync</code>].</p>\n<p>One exchange: the property’s own absence is the answer\n<code>CAP_BATTERY</code> would have given, and over the mesh a capability\nread to learn the same thing is a round trip on the air.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.illuminance\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.illuminance\" class=\"fn\">illuminance</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Fetch a live ambient illuminance reading in millilux\n(<code>PROP_ILLUMINANCE</code>).</p>\n<p><code>Ok(None)</code> means either that the device does not advertise\n<code>CAP_ILLUMINANCE</code>—no light sensor is fitted—or that a device\nwhich does could not read the sensor just now. Both are “there is\nno reading”, which is what a caller acts on; neither is an error.\nLive telemetry, so deliberately not part of [<code>UlcpDevice::sync</code>].</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.alert\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.alert\" class=\"fn\">alert</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;ReportedAlert&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the device’s locate-alert state (<code>PROP_ALERT</code>).</p>\n<p><code>Ok(None)</code> means the device does not advertise <code>CAP_ALERT</code>—it has\nno way to make itself conspicuous.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_alert\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_alert\" class=\"fn\">set_alert</a>(\n    &amp;mut self,\n    state: AlertState,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;ReportedAlert, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Start or stop the device’s locate alert (<code>PROP_ALERT</code>).</p>\n<p>Setting [<code>AlertState::Locate</code>] while an alert is already running\nrestarts the device’s deadline rather than failing, so a host that\nwants an alert to outlast the board’s own bound re-sends this.\nReturns the authoritative state the device reported.</p>\n<p>The alert also ends when someone cancels it at the device or the\ndeadline expires; both arrive as an unsolicited <code>PROP_ALERT</code>\nupdate rather than as a response to this call.</p>\n<p>A device without <code>CAP_ALERT</code> answers <code>STATUS_PROP_NOT_FOUND</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.boot_status\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.boot_status\" class=\"fn\">boot_status</a>(&amp;self) -&gt; Status</h4></section></summary><div class=\"docblock\"><p>Reset cause reported by the device immediately after transport attach.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_policy\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.repeater_policy\" class=\"fn\">repeater_policy</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;RepeaterPolicy&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the device’s full repeater forwarding policy.</p>\n<p><code>Ok(None)</code> means the device does not advertise <code>CAP_REPEATER</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_regions\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.repeater_regions\" class=\"fn\">repeater_regions</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the forwarding filter’s region strings on their own.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_repeater_regions\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_repeater_regions\" class=\"fn\">set_repeater_regions</a>(\n    &amp;mut self,\n    regions: &amp;[<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set which region-tagged floods the device forwards\n(<code>PROP_MAC_REPEATER_REGIONS</code>), as region strings. An empty list\nclears the filter, which imposes no regional restriction rather\nthan blocking every flood.</p>\n<p>Returns the list the device actually stored. A device with less\ncapacity than the caller offered refuses the write outright, so a\nshorter return means it collapsed a repeat.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_repeater_region\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.add_repeater_region\" class=\"fn\">add_repeater_region</a>(\n    &amp;mut self,\n    region: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Add one region to the forwarding filter without resending the rest\nof the table. A region already present fails with <code>STATUS_ALREADY</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_repeater_region\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.remove_repeater_region\" class=\"fn\">remove_repeater_region</a>(\n    &amp;mut self,\n    region: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Remove one region from the forwarding filter. The selector is the\nstring as it was written, not the code it derives to.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_repeater_default_region\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_repeater_default_region\" class=\"fn\">set_repeater_default_region</a>(\n    &amp;mut self,\n    region: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;RegionCode&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;RegionCode&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the region code inserted into untagged floods before\nforwarding (<code>PROP_MAC_REPEATER_DEFAULT_REGION</code>). <code>None</code> forwards\nuntagged.</p>\n<p>Deliberately not cross-checked against\n<a href=\"Self::set_repeater_regions\"><code>set_repeater_regions</code></a>: the two are\nwritten in either order.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_repeater_min_rssi\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_repeater_min_rssi\" class=\"fn\">set_repeater_min_rssi</a>(\n    &amp;mut self,\n    min_rssi: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i16.html\">i16</a>&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i16.html\">i16</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the RSSI floor for forwarding in dBm\n(<code>PROP_MAC_REPEATER_MIN_RSSI</code>). <code>None</code> accepts any.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_repeater_min_snr\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_repeater_min_snr\" class=\"fn\">set_repeater_min_snr</a>(\n    &amp;mut self,\n    min_snr: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i8.html\">i8</a>&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i8.html\">i8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the SNR floor for forwarding in dB\n(<code>PROP_MAC_REPEATER_MIN_SNR</code>). <code>None</code> accepts any.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.meshcore_forwarding\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.meshcore_forwarding\" class=\"fn\">meshcore_forwarding</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;MeshCoreForwarding&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the device’s MeshCore forwarding settings.</p>\n<p><code>Ok(None)</code> means the device does not advertise\n<code>CAP_MESHCORE_FORWARDER</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_meshcore_regions\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_meshcore_regions\" class=\"fn\">set_meshcore_regions</a>(\n    &amp;mut self,\n    regions: &amp;[<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/string/struct.String.html\" title=\"struct alloc::string::String\">String</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the MeshCore regions whose scoped floods the device forwards\n(<code>PROP_MESHCORE_REGIONS</code>). A leading <code>#</code> on a name is dropped: the\ndevice supplies it.</p>\n<p>Returns the list the device actually stored.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_meshcore_region\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.add_meshcore_region\" class=\"fn\">add_meshcore_region</a>(\n    &amp;mut self,\n    region: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Add one MeshCore region. A region already present fails with\n<code>STATUS_ALREADY</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_meshcore_region\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.remove_meshcore_region\" class=\"fn\">remove_meshcore_region</a>(\n    &amp;mut self,\n    region: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Remove one MeshCore region, matched exactly, case included.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_meshcore_forwarding_enabled\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_meshcore_forwarding_enabled\" class=\"fn\">set_meshcore_forwarding_enabled</a>(\n    &amp;mut self,\n    enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set whether MeshCore traffic is forwarded too\n(<code>PROP_MESHCORE_FORWARDING_ENABLED</code>). Enabling fails with\n<code>STATUS_INVALID_STATE</code> under an identity\n[<code>meshcore_identity_allowed</code>] refuses.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_meshcore_region_policy\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_meshcore_region_policy\" class=\"fn\">set_meshcore_region_policy</a>(\n    &amp;mut self,\n    policy: MeshCoreRegionPolicy,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;MeshCoreRegionPolicy, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set how MeshCore transport codes gate flood forwarding\n(<code>PROP_MESHCORE_REGION_POLICY</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.time\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.time\" class=\"fn\">time</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;DeviceTime&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the device’s wall clock and time zone (<code>PROP_TIME</code>,\n<code>PROP_TZ_OFFSET</code>).</p>\n<p><code>Ok(None)</code> means the device does not advertise <code>CAP_TIME</code>.\n<code>Ok(Some(time))</code> with <code>time.epoch == Some(None)</code> means it has one\nand does not know what time it is—the state in which a device with\na screen must show no clock at all.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_time\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_time\" class=\"fn\">set_time</a>(\n    &amp;mut self,\n    epoch: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the device’s wall clock (<code>PROP_TIME</code>). <code>None</code> returns it to not\nknowing what time it is.</p>\n<p>A manual set outranks every receiver-derived one, including while\n<code>PROP_GNSS_TIME_TRUST</code> is clear.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_tz_offset\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_tz_offset\" class=\"fn\">set_tz_offset</a>(&amp;mut self, minutes: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i16.html\">i16</a>) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.i16.html\">i16</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the device’s local time-zone offset in minutes east of UTC\n(<code>PROP_TZ_OFFSET</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.gnss_status\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.gnss_status\" class=\"fn\">gnss_status</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;GnssStatus&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read everything the device reports about positioning\n(<code>PROP_GNSS_*</code>).</p>\n<p><code>Ok(None)</code> means the device does not advertise <code>CAP_GNSS</code>. The fix\nis live telemetry, so a disabled or searching receiver reports\n[<code>GnssSnapshot::SEARCHING</code>] rather than an error.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.advert_policy\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.advert_policy\" class=\"fn\">advert_policy</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;AdvertPolicy&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read the device’s advertisement policy, or <code>None</code> on a device\nwithout <code>CAP_ADVERT</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_advert_interval\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_advert_interval\" class=\"fn\">set_advert_interval</a>(\n    &amp;mut self,\n    seconds: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the seconds between signed identity advertisements, 0 for none\n(<code>PROP_ADVERT_INTERVAL</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_beacon_interval\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_beacon_interval\" class=\"fn\">set_beacon_interval</a>(\n    &amp;mut self,\n    seconds: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the seconds between empty beacons, 0 for none\n(<code>PROP_BEACON_INTERVAL</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_startup_beacon\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_startup_beacon\" class=\"fn\">set_startup_beacon</a>(\n    &amp;mut self,\n    enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set whether one beacon goes out at bring-up (<code>PROP_STARTUP_BEACON</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_gnss_enabled\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_gnss_enabled\" class=\"fn\">set_gnss_enabled</a>(\n    &amp;mut self,\n    enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Power the GNSS receiver on or off (<code>PROP_GNSS_ENABLED</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_gnss_ident_update\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_gnss_ident_update\" class=\"fn\">set_gnss_ident_update</a>(\n    &amp;mut self,\n    enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set whether fixes refresh the advertised node identity’s location\n(<code>PROP_GNSS_IDENT_UPDATE</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_gnss_ident_precision\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_gnss_ident_precision\" class=\"fn\">set_gnss_ident_precision</a>(\n    &amp;mut self,\n    precision: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set the precision the advertised location is clamped to, in\nlocation bytes (<code>PROP_GNSS_IDENT_PRECISION</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_gnss_time_trust\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_gnss_time_trust\" class=\"fn\">set_gnss_time_trust</a>(\n    &amp;mut self,\n    trust: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set whether receiver-derived time may set the wall clock\n(<code>PROP_GNSS_TIME_TRUST</code>).</p>\n<p>Clearing it leaves a manually-set clock proof against a jammed or\nspoofed sky; position reporting is unaffected.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.refresh_t_frame\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.refresh_t_frame\" class=\"fn\">refresh_t_frame</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Refresh the PHY-independent airtime bound. Older devices lack the\nproperty, so read their live LoRa parameters rather than assuming the\nhost’s constructor configuration still describes the radio.</p>\n<p>Fails when the device would not say, or said something unusable;\nthe handle’s own transmits do not depend on that (see\n[<code>Self::refresh_t_frame_or_keep</code>]).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.get_prop\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.get_prop\" class=\"fn\">get_prop</a>(&amp;mut self, key: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Fetch a property’s raw value via <code>CMD_PROP_GET</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.battery_diagnostics\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.battery_diagnostics\" class=\"fn\">battery_diagnostics</a>(\n    &amp;mut self,\n    keys: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;Value&gt;, Status&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Typed optional battery diagnostics. Each property retains not-found,\nunavailable, failed, or valid state. Wire codecs are shared with firmware.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_prop\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_prop\" class=\"fn\">set_prop</a>(\n    &amp;mut self,\n    key: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>,\n    value: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set a property via <code>CMD_PROP_SET</code>, returning the authoritative\nvalue echoed by the device.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.read_each\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.read_each\" class=\"fn\">read_each</a>(\n    &amp;mut self,\n    keys: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, Status&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read several properties, in as few exchanges as the frame and\nreply budgets allow.</p>\n<p>One <code>CMD_PROP_MULTI_GET</code>, continued where the reply ran out of\nroom, and split where the request itself would not fit a frame.\nEvery position comes back either as a value or as the status\nstanding in for one, so an OPTIONAL property’s refusal reads as the\nanswer it is rather than ending the whole read.</p>\n<p><code>PROP_LAST_STATUS</code> must not appear in <code>keys</code>: a refused position\nis reported by putting that very property into it, so its value\nand a refusal are indistinguishable. Read it on its own.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.read_all\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.read_all\" class=\"fn\">read_all</a>&lt;const N: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>&gt;(\n    &amp;mut self,\n    keys: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">N</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;[<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">N</a>], UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read every one of <code>keys</code> in one batch, for a caller that needs them\nall: a refusal anywhere fails the read with the error a lone\n<code>CMD_PROP_GET</code> of that property would have raised.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.get_props\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.get_props\" class=\"fn\">get_props</a>(\n    &amp;mut self,\n    keys: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;(<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;), Status&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read several properties in one exchange via\n<code>CMD_PROP_MULTI_GET</code>.</p>\n<p>Reading continues past failures: a property that could not be\nfetched occupies its own position as an <code>Err</code> carrying the status\na lone <code>CMD_PROP_GET</code> would have produced. A device that answers\nwith fewer entries than were requested ran out of room in the\nresponse; the caller reissues the remainder.</p>\n<p>Host-domain keys are not refused here. Reading one is not writing\nit: a local device answers an administrative handle’s read the\nsame way it answers a tethered one, and over the mesh the\nunreachable half of the property space refuses per position, as\nany other absent property does. Only writes are the host’s alone,\nand [<code>Self::set_prop</code>] still says so.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_props\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_props\" class=\"fn\">set_props</a>(\n    &amp;mut self,\n    entries: &amp;[(<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;)],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;(<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;), Status&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Write several properties in order in one exchange via\n<code>CMD_PROP_MULTI_SET</code>.</p>\n<p>The device applies the writes strictly in order and stops at the\nfirst failure, so the returned entries cover a prefix of the\nrequest: each is either the authoritative value the device echoed\nor the status that ended the sequence. A short reply whose last\nentry succeeded means the device ran out of response space; the\ncaller reissues the remainder.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.insert_prop_item\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.insert_prop_item\" class=\"fn\">insert_prop_item</a>(\n    &amp;mut self,\n    key: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>,\n    item: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Insert one item into a multi-value property via\n<code>CMD_PROP_INSERT</code>, returning the reported form of the inserted\nitem from the correlated <code>CMD_PROP_INSERTED</code>.</p>\n<p><code>item</code> is in the property’s item form with no length prefix.\nA duplicate fails with <code>STATUS_ALREADY</code> unless the property\ndefines replacement semantics (<code>PROP_HOST_PEER_KEYS</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_prop_item\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.remove_prop_item\" class=\"fn\">remove_prop_item</a>(\n    &amp;mut self,\n    key: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>,\n    selector: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Remove one item from a multi-value property via\n<code>CMD_PROP_REMOVE</code>, returning the reported form of the removed\nitem from the correlated <code>CMD_PROP_REMOVED</code>.</p>\n<p><code>selector</code> is the property’s documented remove selector. A\nmissing item fails with <code>STATUS_ITEM_NOT_FOUND</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_drain\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.queue_drain\" class=\"fn\">queue_drain</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Drain the device’s inbound queue (<code>CMD_QUEUE_DRAIN</code>).</p>\n<p>Buffered frames are delivered as ordinary <code>CMD_STR_RECV</code> and land\nin the receive queue for [<code>Radio::poll_receive</code>]; this future\nresolves on the correlated completion status.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_drain_with\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.queue_drain_with\" class=\"fn\">queue_drain_with</a>(\n    &amp;mut self,\n    on_frame: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(&amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>], &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>]),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>As [<code>Self::queue_drain</code>], invoking <code>on_frame</code> with each frame\n(data, trailing metadata bytes) delivered before completion—\nbuffered and interleaved live frames alike. The callback sees\n<strong>every</strong> such frame: an device queue larger than this driver’s\nbounded receive buffer drains losslessly through it. Frames are\nadditionally queued for [<code>Radio::poll_receive</code>], where the\nbounded buffer’s oldest-dropped policy still applies.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.save\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.save\" class=\"fn\">save</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Save the device’s device and host domains to non-volatile storage\n(<code>CMD_SAVE</code>; requires <code>CAP_SAVE</code>).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clear\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.clear\" class=\"fn\">clear</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Erase the device’s saved snapshot and other persisted provisioning\n(<code>CMD_CLEAR</code>; base protocol, BLE bonds and pairing PIN exempt).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.reset\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.reset\" class=\"fn\">reset</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;Status, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Reset the device (<code>CMD_RST</code>) and wait for the reset notification,\nreturning the announced reset status. The device comes up as from\na power cycle—restoring its saved snapshot when one exists,\nfactory configuration otherwise. All session-scoped state and\ncached views are gone; follow with [<code>Self::sync</code>].</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.factory_reset\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.factory_reset\" class=\"fn\">factory_reset</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Factory-reset the device (<code>CMD_FACTORY_RESET</code>): erase ALL mutable\nstate—saved provisioning, the device identity, BLE bonds, and the\npairing PIN—and reboot to a blank factory state. Unlike\n[<code>Self::reset</code>] this sends no expectation of a reply and does not\nwait: the device wipes storage and reboots without responding, which\ndrops the transport link. Treat the ensuing disconnect as\ncompletion; a caller that needs the radio again must re-open the\ntransport and re-pair, since the bond it used is now gone.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.reboot\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.reboot\" class=\"fn\">reboot</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Restart the device (<code>CMD_REBOOT</code>; requires <code>CAP_REBOOT</code>): a power\ncycle that keeps every persisted journal, so the device comes back\nas itself with its saved configuration.</p>\n<p><code>Ok(false)</code> means the device does not advertise <code>CAP_REBOOT</code> and\nnothing was sent—asked rather than sent-and-timed-out, because a\ndevice that <em>will</em> reboot answers nothing at all and waiting for\nsilence cannot tell the two apart. When it does reboot, the link\ndrops; treat the ensuing disconnect as completion.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.enter_dfu\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.enter_dfu\" class=\"fn\">enter_dfu</a>(&amp;mut self, mode: DfuMode) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Enter bootloader DFU after receiving its successful status response.\nA dropped link or timeout never counts as confirmation.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.announce\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.announce\" class=\"fn\">announce</a>(\n    &amp;mut self,\n    request: &amp;Announcement,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Announce the device now (<code>CMD_ANNOUNCE</code>; requires <code>CAP_ADVERT</code>):\nsend an advertisement or a beacon, as a broadcast or on one of the\ndevice’s own channels.</p>\n<p><code>Ok(false)</code> means the device does not advertise <code>CAP_ADVERT</code> and\nnothing was sent. Otherwise the device answers once the\nannouncement is queued for transmission—channel access and the\nduty limit decide later whether it reaches the air, exactly as for\na scheduled announcement.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.i2c_buses\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.i2c_buses\" class=\"fn\">i2c_buses</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;I2cBus&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>The I2C buses a host may drive directly (<code>PROP_I2C_BUSES</code>;\nrequires <code>CAP_I2C</code>), or <code>None</code> when the device has none.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.i2c_devices\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.i2c_devices\" class=\"fn\">i2c_devices</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;I2cPeripheral&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>The peripherals the firmware knows to be on its buses\n(<code>PROP_I2C_DEVICES</code>; requires <code>CAP_I2C</code>), or <code>None</code> when the\ndevice has no bus at all. Returns the firmware’s cached inventory;\nthis query does not initiate identification or a scan.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.i2c_transfer\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.i2c_transfer\" class=\"fn\">i2c_transfer</a>(\n    &amp;mut self,\n    bus: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>,\n    addr: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>,\n    ops: &amp;[Op&lt;'_&gt;],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Perform one I2C transaction (<code>CMD_I2C_TRANSFER</code>; requires\n<code>CAP_I2C</code>) on <code>bus</code> with the 7-bit address <code>addr</code>: the operations\nin order, a repeated START on each change of direction, and one\nSTOP at the end.</p>\n<p>Sends the transfer directly, without a capability or device-table\nquery. <code>Ok(None)</code> means the device returned <code>STATUS_UNIMPLEMENTED</code>;\n<code>Ok(Some(data))</code> is the concatenated read data, empty for a\nwrite-only transfer. The device’s refusals surface as statuses:\n<code>STATUS_NO_DEVICE</code> for an unacknowledged address, <code>STATUS_NACK</code>\nfor a refused data octet, <code>STATUS_BUS_ERROR</code> for the bus itself,\n<code>STATUS_BUSY</code> when the bus or the peripheral is held, and\n<code>STATUS_NOMEM</code> when the read would not fit the binding’s reply.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.i2c_scan\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.i2c_scan\" class=\"fn\">i2c_scan</a>(\n    &amp;mut self,\n    bus: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>,\n    range: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;(<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>, <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>)&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Probe a range of 7-bit addresses on <code>bus</code> (<code>CMD_I2C_SCAN</code>;\nrequires <code>CAP_I2C</code>), <code>None</code> for the default 0x08 through 0x77.</p>\n<p>Sends the scan directly, without a capability or device-table\nquery. <code>Ok(None)</code> means the device returned <code>STATUS_UNIMPLEMENTED</code>;\n<code>Ok(Some(addresses))</code> lists what acknowledged, ascending. A probe\nis a one-octet read, which some peripherals treat as a real\nread, and one that does not acknowledge reads goes unreported,\nso the list is a hint rather than an inventory.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clear_ble_bonds\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.clear_ble_bonds\" class=\"fn\">clear_ble_bonds</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Forget every Bluetooth bond, the pairing PIN, and the pairing\nlockout, then leave the device in a pairing window—the bond\ncount written to zero (<code>PROP_BLE_BOND_COUNT</code>; requires <code>CAP_BLE</code>).</p>\n<p><code>Ok(None)</code> means the device has no Bluetooth transport at all and\nnothing was sent; <code>Ok(Some(count))</code> quotes the count the device\nnow holds. One that has a transport but does not manage its own\nbonds answers <code>STATUS_PROP_NOT_FOUND</code>, which surfaces as an error—\nthe caps list stops at “has Bluetooth”, so the refusal is where the\nrest of the answer lives.</p>\n<p>Over Bluetooth this severs the caller’s own link—the bond that\ncarried it is one of the bonds deleted—but the answer arrives\nfirst; over a cable and over the mesh nothing is disturbed.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_ble_pairing\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_ble_pairing\" class=\"fn\">set_ble_pairing</a>(\n    &amp;mut self,\n    open: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Open or close the pairing window (<code>PROP_BLE_PAIRING</code>; requires\n<code>CAP_BLE</code>). Open, an unbonded host can pair without a gesture at\nthe device; the window also closes by itself, on a new bond or a\ntimeout, which is why it is a property a caller can read back\nrather than a command.</p>\n<p><code>Ok(None)</code> means the device has no Bluetooth transport at all;\n<code>Ok(Some(state))</code> quotes the state the device settled on. A\ndevice that does not manage its own bonds answers\n<code>STATUS_PROP_NOT_FOUND</code>, and one that could not open a window\nright now—locked out, or with Bluetooth disabled—answers\n<code>STATUS_INVALID_STATE</code>; both surface as errors rather than a\nquiet success.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.restore\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.restore\" class=\"fn\">restore</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;RestoreCompletion, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Revert the device to its saved snapshot (<code>CMD_RESTORE</code>; requires\n<code>CAP_SAVE</code>), accepting both spec-permitted completion forms.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_ble_pairing_pin\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.set_ble_pairing_pin\" class=\"fn\">set_ble_pairing_pin</a>(\n    &amp;mut self,\n    pin: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Set or clear the device’s persisted, write-only BLE pairing PIN.</p>\n<p>This property is the protocol’s sole status-only property write: the\nvalue is never echoed. <code>None</code> clears the configured passkey.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.capabilities\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.capabilities\" class=\"fn\">capabilities</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>The device’s capability list (<code>PROP_CAPS</code>), read at most once per\nhandle.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.cached_capabilities\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.cached_capabilities\" class=\"fn\">cached_capabilities</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>]&gt;</h4></section></summary><div class=\"docblock\"><p>The capability list, if this handle has already read it.</p>\n<p>For a caller planning a batch: knowing the list already, it asks\nfor exactly what it needs; not knowing it, it can have the list\nride along with [<code>Self::read_each_with_capabilities</code>] rather than\nspend an exchange learning it first.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.read_each_with_capabilities\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.read_each_with_capabilities\" class=\"fn\">read_each_with_capabilities</a>(\n    &amp;mut self,\n    keys: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;(<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>&gt;, <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/alloc/vec/struct.Vec.html\" title=\"struct alloc::vec::Vec\">Vec</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>&gt;, Status&gt;&gt;), UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Read <code>keys</code> together with the capability list that decides what\nthey mean.</p>\n<p>When the list is not yet known, <code>PROP_CAPS</code> rides at the end of\nthe same batch rather than costing an exchange of its own. Over the\nmesh that is the difference between one exchange and two for every\ngated read. A key the device lacks the capability for comes back\nrefused in its position, which costs a few octets and asks the\ndevice nothing it cannot answer.</p>\n<p>The list goes last so that, should the answer ever be cut across\ntwo exchanges, the entry straddling the cut is the one value that\ncannot have changed in between.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.sync\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.sync\" class=\"fn\">sync</a>(\n    &amp;mut self,\n    expected_host_key: <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">32</a>]&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;DeviceSync, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Run the spec’s post-attach synchronization procedure: fetch the\nretained <code>PROP_LAST_STATUS</code> (detecting a reset since the last\ncontact), the capability list, the configured host identity—\nyielding an ownership verdict against <code>expected_host_key</code>—and\nthe state each advertised capability grants, all in digest form.</p>\n<p>The host must decide ownership before treating queued data as\nits own: [<code>HostOwnership::OtherHost</code>] means the queue and\nprovisioning belong to another identity.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.provision\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.provision\" class=\"fn\">provision</a>(\n    &amp;mut self,\n    desired: &amp;HostProvisioning,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;ProvisionReport, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Establish <code>desired</code> as the device’s complete host domain,\nwriting every part of it unconditionally.</p>\n<p><strong>This does not compare and patch, and that is deliberate.</strong> Key\ntables read back in lossy form only: the device reports channel\nidentifiers and peer public keys, never key material. An\nadministrator can replace a peer’s <code>K_enc</code>/<code>K_mic</code> without\nchanging anything observable, so no comparison over the readable\nsurface can detect it—and a digest over the secret state would\nmean deriving a readable value from key material, which is worse\nthan the problem. The host asserts what it wants; it does not\nreason about what the device already holds.</p>\n<p>Removals still come from comparison, and that is not a\ncontradiction: <em>membership</em> is readable even though key material\nis not. So this reads the digest lists, removes what <code>desired</code>\nomits, and writes everything <code>desired</code> contains regardless of\nwhat came back.</p>\n<p>The host domain is volatile across power cycles, so the usual\ncase is a device that has just rebooted and holds nothing. When\nit has <em>not</em> rebooted the rewrite is redundant—that is the\npoint. Correctness must not depend on detecting which case this\nis, because reboot detection would also have to cover partial\nprovisioning, another administrator having intervened, and future\ndevice behavior changes.</p>\n<p>Each individual write is transactional on the device (spec\n§Mutation Atomicity); the <em>sequence</em> is not (see the ULCP\ntransition plan, decision 7). An interrupted call leaves a\nmixture, which the next call repairs by rewriting everything.</p>\n<p>Provisioning is per item rather than per table wherever the table\ncan grow: a whole peer table stops fitting in a frame at the\nfifth entry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.ensure_device_identity\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.ensure_device_identity\" class=\"fn\">ensure_device_identity</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">32</a>], UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>The device’s device identity public key, generating one on-device\nif none is configured (<code>CAP_DEV_IDENTITY</code>; generation requires\nthe transport’s provisioning-security binding).</p>\n<p>On-device generation is the spec-recommended form: the private\nkey never exists anywhere but the radio, and only the resulting\npublic key crosses the link.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.pop_prop_event\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.pop_prop_event\" class=\"fn\">pop_prop_event</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;PropEvent&gt;</h4></section></summary><div class=\"docblock\"><p>Take the oldest retained unsolicited property notification.</p>\n<p>Events accumulate while other calls read from the link (bounded\nat [<code>PROP_EVENT_DEPTH</code>], oldest dropped first).</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmit_raw_with_meta\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.transmit_raw_with_meta\" class=\"fn\">transmit_raw_with_meta</a>(\n    &amp;mut self,\n    data: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    metadata: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, TxError&lt;UlcpError&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Transmit a frame with a caller-supplied <code>STR_PHY_RAW</code> metadata\nblock, byte for byte.</p>\n<p>[<code>Radio::transmit</code>] composes the metadata from [<code>TxOptions</code>],\nwhich is what a MAC wants. A bridge does not: it relays frames\nwhose transmit parameters were decided elsewhere, and must be\nable to put exactly those bytes on the wire—including fields\n[<code>TxOptions</code>] has no vocabulary for, such as a power override.</p>\n<p>The channel-access retry budget comes from the metadata itself:\nwith <code>TX_FLAG_NOCCA</code> clear the device performs CCA and a busy\nchannel fails immediately with [<code>TxError::CadTimeout</code>], leaving\nthe retry policy to the caller.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_receive_raw\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.poll_receive_raw\" class=\"fn\">poll_receive_raw</a>(\n    &amp;mut self,\n    cx: &amp;mut <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/core/task/wake/struct.Context.html\" title=\"struct core::task::wake::Context\">Context</a>&lt;'_&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/task/poll/enum.Poll.html\" title=\"enum core::task::poll::Poll\">Poll</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;RawRxFrame, UlcpError&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Poll for one inbound frame, preserving its metadata bytes.</p>\n<p>[<code>Radio::poll_receive</code>] decodes the metadata into [<code>RxInfo</code>],\nwhich cannot represent it faithfully: the “unsupported” sentinels\ncollapse to zero and the buffered-frame extension is discarded\nentirely. A bridge relays the metadata rather than interpreting\nit, so it needs the bytes.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.receive_raw\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.receive_raw\" class=\"fn\">receive_raw</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;RawRxFrame, UlcpError&gt;</h4></section></summary><div class=\"docblock\"><p>Await one inbound frame with its metadata bytes intact.</p>\n<p>Cancel-safe: the frame is only removed from the inbound queue\nonce this future is ready to return it.</p>\n</div></details></div></details>",0,"umshctl::mesh::CtlRadio"]]]]);
    if (window.register_type_impls) {
        window.register_type_impls(type_impls);
    } else {
        window.pending_type_impls = type_impls;
    }
})()
